=== case_id ===
Case-28-veggie-price-007

=== 用户原始指令 (query.txt) ===
帮我整个菜价卡呗，显示一行菜价数字，点一下跳app，能从日历看做饭日程，能看到已比完的

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整个菜价卡呗，显示一行菜价数字，点一下跳app，能从日历看做饭日程，能看到已比完的",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "summary": {
      "title": {
        "type": "string",
        "description": "菜价比价卡片标题",
        "sampleValue": "菜价比价"
      },
      "priceValue": {
        "type": "string",
        "description": "当前蔬菜比价后的单行价格数字",
        "sampleValue": "3.98"
      },
      "unitText": {
        "type": "string",
        "description": "价格单位展示文本",
        "sampleValue": "元/斤"
      },
      "comparedText": {
        "type": "string",
        "description": "已完成比价的摊位或渠道数量",
        "sampleValue": "已比12家"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日历做饭日程唯一标识符",
              "sampleValue": "cook_20260709_dinner"
            },
            "title": {
              "type": "string",
              "description": "日历中的做饭日程标题",
              "sampleValue": "晚餐做饭"
            },
            "dtStart": {
              "type": "string",
              "description": "做饭日程当天开始时间",
              "sampleValue": "18:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "做饭日程当天结束时间",
              "sampleValue": "19:30"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": []
}

